/*
 * O seletor de emoji do Discourse: busca no topo, a fileira de categorias,
 * a grade rolável com um título por categoria (os "Usados recentemente"
 * primeiro) e, embaixo, o emoji sob o mouse com o atalho dele e a escolha do
 * tom de pele.
 *
 * Abre como um balão preso ao botão da barra do editor, num contêiner no
 * <body>: dentro do composer ele seria cortado pela borda de cima.
 */
import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import { TONES, getRecent, getTone, loadEmojiData, matches, normalize, pushRecent, setTone, twemojiUrl, usesTwemoji, withTone } from './emojiUtils';
import { t } from '../../../utils/settings';

/** Os ícones das categorias, na ordem do Discourse. */
const GROUP_ICONS = {
  recent: 'far fa-clock',
  smileys: 'far fa-face-smile',
  people: 'far fa-hand',
  nature: 'fas fa-leaf',
  food: 'fas fa-burger',
  activities: 'far fa-futbol',
  travel: 'fas fa-plane',
  objects: 'far fa-lightbulb',
  symbols: 'fas fa-icons',
  flags: 'far fa-flag'
};

/** Mais que isso numa busca vira ruído; o Discourse também corta. */
const SEARCH_LIMIT = 120;
export default class EmojiPicker extends Component {
  groups = null;
  byChar = new Map();
  query = '';
  activeGroup = 'smileys';
  tone = getTone();
  toneOpen = false;
  hovered = null;
  twemoji = usesTwemoji();
  oninit(vnode) {
    super.oninit(vnode);
    loadEmojiData().then(groups => {
      this.groups = groups;
      groups.forEach(group => group.emoji.forEach(row => this.byChar.set(row[0], row)));
      if (getRecent().length) this.activeGroup = 'recent';
      m.redraw();
    });
  }
  oncreate(vnode) {
    super.oncreate(vnode);

    // No celular o teclado virtual cobriria metade do seletor: o foco na
    // busca fica só para quem tem mouse.
    if (app.screen() !== 'phone') this.element.querySelector('.CanelaEmojiPicker-search input')?.focus();
  }
  view() {
    return m("div", {
      className: "CanelaEmojiPicker",
      role: "dialog",
      "aria-label": t('composer.emoji.title')
    }, m("div", {
      className: "CanelaEmojiPicker-header"
    }, m("div", {
      className: "CanelaEmojiPicker-search"
    }, m(Icon, {
      name: "fas fa-magnifying-glass"
    }), m("input", {
      type: "search",
      className: "FormControl",
      placeholder: t('composer.emoji.search_placeholder'),
      value: this.query,
      oninput: e => {
        this.query = e.target.value;
        this.hovered = null;
      },
      onkeydown: e => this.onSearchKey(e)
    })), m("button", {
      type: "button",
      className: "Button Button--icon Button--link CanelaEmojiPicker-close",
      "aria-label": t('composer.emoji.close'),
      onclick: () => this.attrs.onclose()
    }, m(Icon, {
      name: "fas fa-xmark"
    }))), !this.query && this.groups && m("nav", {
      className: "CanelaEmojiPicker-groups"
    }, this.groupButtons()), m("div", {
      className: "CanelaEmojiPicker-body",
      onscroll: e => this.trackScroll(e)
    }, this.groups ? this.content() : m(LoadingIndicator, null)), m("div", {
      className: "CanelaEmojiPicker-footer"
    }, m("div", {
      className: "CanelaEmojiPicker-info"
    }, this.hovered ? m('[', null, this.emojiImage(withTone(this.hovered, this.tone), 'CanelaEmojiPicker-infoEmoji'), m("code", null, ":", this.hovered[1].split(' ')[0], ":")) : m("span", {
      className: "CanelaEmojiPicker-hint"
    }, t('composer.emoji.hint'))), this.toneSelector()));
  }
  groupButtons() {
    const keys = [...(getRecent().length ? ['recent'] : []), ...this.groups.map(group => group.key)];
    return keys.map(key => m("button", {
      type: "button",
      className: classList('CanelaEmojiPicker-group', {
        active: key === this.activeGroup
      }),
      title: t(`composer.emoji.groups.${key}`),
      "aria-label": t(`composer.emoji.groups.${key}`),
      onclick: () => this.scrollTo(key)
    }, m(Icon, {
      name: GROUP_ICONS[key] || 'far fa-face-smile'
    })));
  }
  content() {
    if (this.query.trim()) {
      const terms = normalize(this.query).split(/\s+/).filter(Boolean);
      const results = [];
      for (const group of this.groups) {
        for (const row of group.emoji) {
          if (matches(row, terms)) results.push(row);
          if (results.length >= SEARCH_LIMIT) break;
        }
        if (results.length >= SEARCH_LIMIT) break;
      }
      return results.length ? this.grid(results) : m("p", {
        className: "CanelaEmojiPicker-empty"
      }, t('composer.emoji.no_results'));
    }
    const recent = getRecent().map(char => this.byChar.get(char)).filter(row => !!row);

    // Sem `null` no lugar de "Recentes": as seções têm key, e o Mithril
    // recusa uma lista que mistura itens com e sem key.
    const sections = this.groups.map(group => this.section(group.key, group.emoji));
    return recent.length ? [this.section('recent', recent), ...sections] : sections;
  }
  section(key, rows) {
    return m("section", {
      key: key,
      className: "CanelaEmojiPicker-section",
      "data-group": key
    }, m("h4", {
      className: "CanelaEmojiPicker-sectionTitle"
    }, t(`composer.emoji.groups.${key}`)), this.grid(rows));
  }
  grid(rows) {
    return m("div", {
      className: "CanelaEmojiPicker-grid"
    }, rows.map(row => {
      const emoji = withTone(row, this.tone);
      return m("button", {
        type: "button",
        className: "CanelaEmojiPicker-emoji",
        title: `:${row[1].split(' ')[0]}:`,
        onclick: () => this.select(row),
        onmouseenter: () => this.hovered = row,
        onfocus: () => this.hovered = row
      }, this.emojiImage(emoji));
    }));
  }
  emojiImage(emoji, className = '') {
    if (!this.twemoji) return m("span", {
      className: classList('CanelaEmojiPicker-char', className)
    }, emoji);
    return m("img", {
      className: classList('emoji', className),
      src: twemojiUrl(emoji),
      alt: emoji,
      loading: "lazy",
      draggable: false
    });
  }
  toneSelector() {
    return m("div", {
      className: classList('CanelaEmojiPicker-tones', {
        open: this.toneOpen
      })
    }, this.toneOpen ? TONES.map((_, tone) => m("button", {
      type: "button",
      className: classList('CanelaEmojiPicker-tone', `CanelaEmojiPicker-tone--${tone}`, {
        active: tone === this.tone
      }),
      "aria-label": t(`composer.emoji.tones.${tone}`),
      title: t(`composer.emoji.tones.${tone}`),
      onclick: () => {
        this.tone = tone;
        this.toneOpen = false;
        setTone(tone);
      }
    })) : m("button", {
      type: "button",
      className: classList('CanelaEmojiPicker-tone', `CanelaEmojiPicker-tone--${this.tone}`, 'active'),
      "aria-label": t('composer.emoji.tone_label'),
      title: t('composer.emoji.tone_label'),
      onclick: () => this.toneOpen = true
    }));
  }
  select(row) {
    pushRecent(row[0]);
    this.attrs.onselect(withTone(row, this.tone));
  }

  /** Enter na busca insere o primeiro resultado, como no Discourse. */
  onSearchKey(e) {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      this.attrs.onclose();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      this.element.querySelector('.CanelaEmojiPicker-emoji')?.click();
    }
  }
  scrollTo(key) {
    const body = this.element.querySelector('.CanelaEmojiPicker-body');
    const section = this.element.querySelector(`.CanelaEmojiPicker-section[data-group="${key}"]`);
    if (!body || !section) return;
    body.scrollTop = section.offsetTop - body.offsetTop;
    this.activeGroup = key;
  }

  /** A categoria em destaque acompanha a rolagem da grade. */
  trackScroll(e) {
    const body = this.element.querySelector('.CanelaEmojiPicker-body');
    if (!body) return;
    const sections = Array.from(body.querySelectorAll('.CanelaEmojiPicker-section'));
    const top = body.scrollTop + body.offsetTop + 8;
    const current = sections.filter(section => section.offsetTop <= top).pop() || sections[0];
    const key = current?.dataset.group;

    // Rolar só redesenha quando a categoria muda: a grade tem 2 mil botões.
    if (key && key !== this.activeGroup) this.activeGroup = key;else e.redraw = false;
  }
}

// ─── O balão ────────────────────────────────────────────────────────────────

let portal = null;
let cleanup = null;
export function closeEmojiPicker() {
  cleanup?.();
}

/**
 * Abre o seletor preso a `anchor` (o botão da barra). Fica acima do botão
 * quando há espaço — o editor está embaixo da tela — e nunca sai pela
 * lateral. No celular o CSS o transforma numa folha presa ao rodapé.
 */
export function openEmojiPicker(anchor, onselect) {
  if (cleanup) {
    cleanup();
    return;
  }
  portal = document.createElement('div');
  portal.className = 'CanelaEmojiPicker-portal';
  document.body.appendChild(portal);
  const position = () => {
    if (!portal || app.screen() === 'phone') return;
    const rect = anchor.getBoundingClientRect();
    const width = portal.offsetWidth;
    const height = portal.offsetHeight;
    const above = rect.top - height - 8;
    portal.style.top = `${above >= 8 ? above : Math.min(rect.bottom + 8, window.innerHeight - height - 8)}px`;
    portal.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - width - 8))}px`;
  };
  const close = () => {
    document.removeEventListener('mousedown', outside, true);
    window.removeEventListener('resize', position);
    if (portal) {
      m.mount(portal, null);
      portal.remove();
    }
    portal = null;
    cleanup = null;
  };
  const outside = e => {
    const target = e.target;
    if (portal?.contains(target) || anchor.contains(target)) return;
    close();
  };
  cleanup = close;
  m.mount(portal, {
    view: () => m(EmojiPicker, {
      onselect: emoji => {
        close();
        onselect(emoji);
      },
      onclose: close
    })
  });
  position();
  // A primeira medida sai antes de a lista carregar; a altura do balão é
  // fixa no CSS, então uma segunda conta depois do desenho basta.
  requestAnimationFrame(position);
  document.addEventListener('mousedown', outside, true);
  window.addEventListener('resize', position);
}
flarum.reg.add('ramon-canela', 'forum/features/composer/emoji/EmojiPicker', EmojiPicker);